import Foundation

/// 剪貼簿歷史：只記文字、只放在記憶體（不寫進硬碟），最多 limit 筆。密碼工具標成機密、暫時或自動產生的內容
/// （nspasteboard.org 的標記）一律不記。只做整理，讀剪貼簿在 ClipboardHistoryController
struct ClipboardHistory {
    static let limit = 30
    /// 每筆最多幾個字
    static let maxLength = 10_000
    /// 有這些類型就不記：密碼工具複製密碼時會加上
    static let skippedTypes: Set<String> = [
        "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType", "org.nspasteboard.AutoGeneratedType",
    ]

    private(set) var items: [String] = []

    static func shouldRecord(types: [String]) -> Bool { skippedTypes.isDisjoint(with: types) }

    mutating func add(_ text: String) {
        guard !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return }
        let trimmed = String(text.prefix(Self.maxLength))
        items.removeAll { $0 == trimmed }
        items.insert(trimmed, at: 0)
        if items.count > Self.limit { items.removeLast(items.count - Self.limit) }
    }

    mutating func clear() { items = [] }

    /// 選單上的一行預覽
    static func preview(_ text: String) -> String {
        let line = text.split(whereSeparator: \.isNewline).map { $0.trimmingCharacters(in: .whitespaces) }.filter { !$0.isEmpty }.joined(separator: " ")
        return line.count > 48 ? String(line.prefix(48)) + "…" : line
    }
}
